/**
 * js-css-studio rule model and persistence shape.
 *
 * Pure functions so the scoping rules, validation, and the built-in snippets can
 * be tested without CodeMirror or a DOM. The editor UI is in `panel.ts`.
 */

/** Where a rule applies. */
export type RuleScope = 'domain' | 'global';

/** A saved snippet. */
export interface StudioRule {
  /** Stable id; generated by the caller. */
  id: string;
  name: string;
  kind: 'js' | 'css';
  code: string;
  scope: RuleScope;
  /** Target domain when `scope === 'domain'`; ignored otherwise. */
  domain: string;
  /** Run automatically on page load. */
  autoRun: boolean;
  enabled: boolean;
  updatedAt: string;
}

/** Storage keys. One JSON array under `rules`, plus small settings. */
export const STORAGE_KEY_RULES = 'rules';

/** Cap so a runaway page cannot fill D1. */
export const MAX_RULES = 100;
export const MAX_CODE_LENGTH = 200_000;

export interface StudioSettings {
  autoRunEnabled: boolean;
}

export const DEFAULT_SETTINGS: StudioSettings = { autoRunEnabled: true };

/** A one-tap utility snippet. */
export interface BuiltinSnippet {
  id: string;
  label: string;
  description: string;
  kind: 'js' | 'css';
  code: string;
}

/**
 * The three built-in mobile utilities.
 *
 * These are deliberately conservative: each restores something a site removed
 * for its own reasons, and none of them touch authentication, paywalls, or
 * another origin.
 */
export const BUILTIN_SNIPPETS: readonly BuiltinSnippet[] = [
  {
    id: 'restore-copy',
    label: 'Re-enable copy & selection',
    description: 'Undo right-click, copy and text-selection blocking.',
    kind: 'js',
    code: `// Re-enable copy, right-click and text selection.
for (const type of ['contextmenu', 'copy', 'cut', 'selectstart', 'dragstart']) {
  document.addEventListener(type, (e) => e.stopPropagation(), true);
}
document.querySelectorAll('[oncontextmenu]').forEach((el) => el.removeAttribute('oncontextmenu'));
const style = document.createElement('style');
style.textContent = '*{-webkit-user-select:text!important;user-select:text!important}';
document.head.appendChild(style);
console.log('[mirenda] copy & selection restored');`,
  },
  {
    id: 'reveal-passwords',
    label: 'Reveal password fields',
    description: 'Turn password inputs into plain text so you can check a typo.',
    kind: 'js',
    code: `// Reveal password inputs. Does not read or transmit the values.
document.querySelectorAll('input[type="password"]').forEach((input) => {
  input.type = 'text';
  input.style.webkitTextSecurity = 'none';
});
console.log('[mirenda] password fields revealed');`,
  },
  {
    id: 'remove-overlays',
    label: 'Remove sticky overlays',
    description: 'Strip fixed/sticky banners, modals and cookie walls.',
    kind: 'css',
    code: `/* Remove fixed and sticky overlays that cover the page. */
[style*="position: fixed"], [style*="position:fixed"],
[style*="position: sticky"], [style*="position:sticky"],
[class*="cookie"], [id*="cookie"], [class*="consent"],
[class*="paywall"], [class*="newsletter"], [class*="subscribe"] {
  display: none !important;
}
html, body {
  overflow: auto !important;
  position: static !important;
}`,
  },
];

/** A fresh rule with sensible defaults. */
export function createRule(input: {
  id: string;
  name: string;
  kind: 'js' | 'css';
  code: string;
  scope: RuleScope;
  domain: string;
  now?: Date;
}): StudioRule {
  return {
    id: input.id,
    name: input.name.trim(),
    kind: input.kind,
    code: input.code,
    scope: input.scope,
    domain: input.scope === 'domain' ? input.domain.toLowerCase() : '',
    autoRun: false,
    enabled: true,
    updatedAt: (input.now ?? new Date()).toISOString(),
  };
}

/** Validation problems for a rule. Empty means valid. */
export function validateRule(rule: Pick<StudioRule, 'name' | 'code' | 'scope' | 'domain'>): string[] {
  const problems: string[] = [];
  if (rule.name.trim() === '') problems.push('Give the snippet a name.');
  if (rule.name.length > 120) problems.push('Name must be at most 120 characters.');
  if (rule.code.trim() === '') problems.push('The snippet is empty.');
  if (rule.code.length > MAX_CODE_LENGTH) problems.push('Snippet is too large.');
  if (rule.scope === 'domain' && rule.domain.trim() === '') {
    problems.push('A domain-scoped snippet needs a domain.');
  }
  return problems;
}

/**
 * Does this rule apply to `url`? Global rules always do; a domain rule matches
 * the host and its subdomains, so `example.com` covers `www.example.com`.
 */
export function ruleAppliesTo(rule: StudioRule, url: string): boolean {
  if (!rule.enabled) return false;
  if (rule.scope === 'global') return true;
  let host: string;
  try {
    host = new URL(url).hostname.toLowerCase();
  } catch {
    return false;
  }
  const domain = rule.domain.replace(/^\./, '').toLowerCase();
  if (domain === '') return false;
  return host === domain || host.endsWith(`.${domain}`);
}

/** Rules that should auto-run for a page load, in save order. */
export function autoRunRules(rules: readonly StudioRule[], url: string): StudioRule[] {
  return rules.filter((rule) => rule.autoRun && ruleAppliesTo(rule, url));
}

/** Every rule that applies, for a manual "run all" action. */
export function applicableRules(rules: readonly StudioRule[], url: string): StudioRule[] {
  return rules.filter((rule) => ruleAppliesTo(rule, url));
}

/**
 * Parse the stored rules array defensively: a corrupt row must degrade to an
 * empty list rather than break the panel.
 */
export function parseRules(raw: unknown): StudioRule[] {
  if (!Array.isArray(raw)) return [];
  const rules: StudioRule[] = [];
  for (const entry of raw) {
    if (typeof entry !== 'object' || entry === null) continue;
    const e = entry as Record<string, unknown>;
    if (typeof e.id !== 'string' || typeof e.name !== 'string' || typeof e.code !== 'string') continue;
    const kind = e.kind === 'css' ? 'css' : 'js';
    const scope: RuleScope = e.scope === 'global' ? 'global' : 'domain';
    rules.push({
      id: e.id,
      name: e.name,
      kind,
      code: e.code,
      scope,
      domain: typeof e.domain === 'string' ? e.domain : '',
      autoRun: e.autoRun === true,
      enabled: e.enabled !== false,
      updatedAt: typeof e.updatedAt === 'string' ? e.updatedAt : new Date().toISOString(),
    });
    if (rules.length >= MAX_RULES) break;
  }
  return rules;
}

/** Insert or replace a rule by id, keeping the newest 100. */
export function upsertRule(rules: readonly StudioRule[], rule: StudioRule): StudioRule[] {
  const next = rules.filter((existing) => existing.id !== rule.id);
  next.push(rule);
  return next.slice(-MAX_RULES);
}

/** Remove a rule by id. */
export function removeRule(rules: readonly StudioRule[], id: string): StudioRule[] {
  return rules.filter((rule) => rule.id !== id);
}

/**
 * Generate a collision-resistant id without `crypto.randomUUID`, which is not
 * available in every sandboxed frame.
 */
export function generateRuleId(now = Date.now(), random = Math.random()): string {
  return `r${now.toString(36)}${Math.floor(random * 1e6).toString(36)}`;
}
